// CONFIGURACIÓN: un bloque por canal de salida. Para añadir un canal nuevo, copia el bloque
// con su canal de YouTube (id UC... conectado en ClipsKitty), su cuenta de TikTok en WoopSocial
// y sus canales fuente (id UC... del canal vigilado en ClipsKitty: 'nombre que sale en el título').
const CANALES = [
  {
    nombre: 'Clippendo',
    youtube_channel_id: 'UCEQOoBRLPLdM61n6BgZ4KAA',
    tiktok_account_id: '',
    fuentes: {
      'UCaY_-ksFSQtTGk0y1HA_3YQ': 'Ibai',
      'UCyQqzYXQBUWgBTn4pw_fFSQ': 'AuronPlay',
      'UCXazgXDIYyWH-yXLAkcrFxw': 'Rubius',
      'UCCEmjNPpJYhGDgaEqeeA4HA': 'TheGrefg',
      'UC06rPIABrthG0hwLTVhINLA': 'ElMariana',
      'UCKvoBRFqMNqvuSvFBiNadgw': 'IlloJuan',
      'UC9c4rND1mNP-XrWQjbFxp8g': 'ElXokas',
      'UCOBtOqxsioUI-fFykO2I4BQ': 'Peereira',
      'UCdhcvooVFqcc2eQUwM38J3Q': 'Carola',
      'UC1Bb0DVSgXLKuLbenbpkb8g': 'Agustin51',
      'UCdvyCPDTkkfd4MwqD7ZkGgg': 'Juan Guarnizo',
      'UCgTOIiEgjm58xLjHvDjmgdA': 'Spreen',
      'UCam8T03EOFBsNdR0thrFHdQ': 'Vegetta777',
      'UC4LHNX8d8RqnDX0OezgmCTg': 'Willyrex',
      'UCqJ5zFEED1hWs0KNQCQuYdQ': 'Mikecrack',
      'UCW3bX8K5LuQHw8cKc3U8iUg': 'Rivers',
      'UCdgKwvFibviy0AzNJCxOQLQ': 'AriGameplays',
      'UC_8NknAFiyhOUaZqHR3lq3Q': 'Quackity',
      'UCjmHiHCOYEUNMdJujiBQOqQ': 'ElDed',
      'UCG8eSYvOQUpb9HM8zU5d6xg': 'Robleis',
      'UCh715KhLM7vbOwozSXLWI_w': 'Alexby11',
      'UCvZ0P9-EmGz6SFUuFiZPXKw': 'Coscu',
      'UCiivq2F50ddJ7BkBGILuTKQ': 'Davoo Xeneize',
      'UCJmMn2PUwpU3TXYZB4i_HuA': 'Invictor',
      'UCI2FmVp--YL8d7iVFt8mmxg': 'ElTrollino',
      'UCl8bYBm0XAP23mReE11IBOA': 'YoSoyPlex',
      'UCi7TVXyvrIwqeS9tfYD8UDA': 'DjMaRiiO',
      'UC7QiWlK7a7RePg3krLeBK0w': 'Lolito',
      'UCHkh8YFg0l4tkY6_zvzdd5w': 'Luzu',
      'UCEg_iK8FKwZfpRMn4-AnnnQ': 'Westcol'
    },
  },
];
const DIAS_MAX = 7; // solo vídeos procesados en los últimos 7 días

const creadorACanal = {};
for (const w of $('Kitty - Canales vigilados').all()) {
  if (w.json.creator && w.json.creator.id != null) creadorACanal[w.json.creator.id] = w.json.channel_key;
}
const limite = Date.now() - DIAS_MAX * 864e5;
const out = [];
for (const item of $input.all()) {
  const v = item.json;
  if (!v.video_id || String(v.video_id).startsWith('local_')) continue; // VODs locales fuera
  if (v.status !== 'done') continue;
  if (Date.parse(v.updated_at || v.created_at || 0) < limite) continue;
  const key = String(v.channel_id || '').startsWith('UC') ? v.channel_id : creadorACanal[v.creator_id];
  const c = CANALES.findIndex(cn => cn.fuentes[key]);
  if (c < 0) continue;
  out.push({ json: {
    video_id: v.video_id, video_titulo: v.title, video_fecha: v.created_at,
    canal: CANALES[c].nombre, youtube_channel_id: CANALES[c].youtube_channel_id,
    tiktok_account_id: CANALES[c].tiktok_account_id, streamer: CANALES[c].fuentes[key],
  } });
}
return out;

// Los 2 mejores clips de cada vídeo, solo si tienen 80 puntos o más.
const MIN_PUNTOS = 80, POR_VIDEO = 2;
const videos = {};
for (const v of $('Videos de los canales').all()) videos[v.json.video_id] = v.json;
const porVideo = {};
for (const item of $input.all()) {
  const c = item.json;
  if (!videos[c.video_id] || !c.path || !(c.score >= MIN_PUNTOS)) continue;
  (porVideo[c.video_id] = porVideo[c.video_id] || []).push(c);
}
const out = [];
for (const [vid, clips] of Object.entries(porVideo)) {
  clips.sort((a, b) => b.score - a.score);
  for (const c of clips.slice(0, POR_VIDEO)) out.push({ json: { ...videos[vid], clip: c } });
}
return out;

// Por cada canal de salida, el siguiente clip pendiente: vídeo más reciente primero, luego puntuación.
const elegidos = {};
for (const e of $('Top 2 por video (80+)').all()) elegidos[e.json.clip.id] = e.json;
const porCanal = {};
for (const p of $input.all()) {
  const e = elegidos[p.json.clip_id];
  if (!e) continue;
  // Cualquier publicación previa (también fallida) cuenta: no se reintenta sola.
  const hechas = new Set((p.json.posts || []).map(x => x.platform));
  const falta_youtube = !hechas.has('youtube'), falta_tiktok = !hechas.has('tiktok');
  if (falta_youtube || falta_tiktok) (porCanal[e.canal] = porCanal[e.canal] || []).push({ e, falta_youtube, falta_tiktok });
}
const out = [];
for (const lista of Object.values(porCanal)) {
  lista.sort((a, b) => String(b.e.video_fecha).localeCompare(String(a.e.video_fecha)) || (b.e.clip.score - a.e.clip.score));
  const { e, falta_youtube, falta_tiktok } = lista[0];
  const clip = e.clip;
  const tags = [];
  let largo = 0;
  for (const t of (clip.hashtags || [])) {
    const tag = String(t).replace(/^#/, '').trim();
    if (!tag || largo + tag.length + 1 > 480) continue;
    tags.push(tag); largo += tag.length + 1;
  }
  const descripcion = String(clip.description || '').slice(0, 4000);
  const hashtags = tags.map(t => '#' + t.replace(/\s+/g, '')).join(' ');
  out.push({ json: {
    canal: e.canal, youtube_channel_id: e.youtube_channel_id, tiktok_account_id: e.tiktok_account_id,
    clip_id: clip.id, score: clip.score, video_id: e.video_id, streamer: e.streamer,
    titulo: `${e.streamer} - ${clip.title || clip.hook || 'Clip'}`.slice(0, 100),
    descripcion, tags, descripcion_youtube: [descripcion, hashtags].filter(Boolean).join('\n\n'),
    falta_youtube, falta_tiktok, pendientes_en_cola: lista.length,
  } });
}
return out;
